"""
This module provides functionality related to Egate telnet console.

Classes:
- :class:`EgateConsole`: Streamlines sending commands to the EgateConsole.
"""

from taf.internal.managedobject import ManagedObject
from .exceptions import EgateConsoleSetupFailure
from .logger import logger
from socket import timeout as timeout_exc
from pyte import Stream, Screen


class VTEmuDecoder(object):
    """ A basic implementation of decoder for EgateConsole output.

    This uses pyte library to emulate a virtual terminal, so that the ANSII
    sequences are parsed.
    """
    EGATE_SCREEN_WIDTH = 80

    def decode(self, data):
        data = data.decode()
        no_lines = data.count('\n')
        screen = Screen(self.EGATE_SCREEN_WIDTH, no_lines)
        stream = Stream(screen)

        stream.feed(data)
        return '\n'.join(screen.display)


class EgateConsole(ManagedObject):
    """ This class wraps around Egate telnet session and automates sending
    commands to it / receiving the output from it.

    Methods:
    - :meth:`execute`: send a command to egate console, await prompt and return
    output.
    - :meth:`setup`: connect to the Egate console, wait for prompt. If waiting
    for prompt times out (takes longer than setup_timeout specified in init),
    EgateConsoleSetupFailure is raised.
    """
    PROMPT = "EGATE> "
    DEFAULT_DECODER = VTEmuDecoder

    # TODO: Add method docstrings

    def __init__(self, telnet_session, l3, edaemon, egate, setup_timeout=5.0,
                 *args, **kwargs):
        super(EgateConsole, self).__init__(**kwargs)
        self.add_prerequisite(l3)
        self.add_prerequisite(edaemon)
        self.add_prerequisite(egate)
        self.add_prerequisite(telnet_session)

        self.logger = logger.getChild(self.__class__.__name__)
        self._telnet_session = telnet_session
        self._setup_timeout = setup_timeout
        self.decoder = self.DEFAULT_DECODER()

    def _setup(self):
        if not self._client_is_on_prompt(self._setup_timeout):
            exc_msg = "Timed out while waiting for the first console prompt."
            raise EgateConsoleSetupFailure(exc_msg)
        else:
            self.logger.info("EgateConsole connection setup done.")

    def _client_is_on_prompt(self, timeout):
        try:
            self.read_until_prompt(timeout)
        except timeout_exc:
            return False
        return True

    def _log_output(self, output):
        self.logger.debug("Egate output:")
        self.logger.debug(output)

    def read_output(self):
        output = self._telnet_session.read_some()
        output = self.decoder.decode(output)
        self._log_output(output)
        return output

    def read_output_until(self, expected, timeout=None):
        self._log_reading_until("Reading output until \"{expected}\".",
                                expected, timeout)

        output = self._read_until(expected, timeout)
        return output

    def read_until_prompt(self, timeout=None):
        self._log_reading_until("Reading until prompt (\"{expected}\").",
                                self.PROMPT, timeout)

        output = self._read_until(self.PROMPT, timeout)
        output = self._remove_prompt_from_output(output)

        return output

    def _log_reading_until(self, log_msg, expected, timeout):
        if timeout is not None:
            log_msg += " Timeout: {timeout} seconds."
        log_msg = log_msg.format(expected=expected, timeout=timeout)
        self.logger.debug(log_msg)

    def _remove_prompt_from_output(self, output):
        return output.replace(self.PROMPT, '')

    def _read_until(self, expected, timeout):
        output = self._telnet_session.read_until(expected.encode(), timeout)
        output = self.decoder.decode(output)
        self._log_output(output)
        if expected not in output and timeout is not None:
            raise timeout_exc('read timed out.')

        return output

    def execute(self, command, timeout=None):
        self.logger.info("Sending \"{}\" to egate console.".format(command))

        command = command + '\n'
        self._telnet_session.write(command.encode())

    def _teardown(self):
        self.execute('exit')
